<script setup lang="ts">
import type {Notice,NoticeOptions} from '../../../shared/types'
const session=useSession(),notices=ref<Notice[]>([]),noticeOptions=ref<NoticeOptions>({categories:[],priorities:[]}),loading=ref(true),error=ref(''),search=ref('')
const optionLabel=(options:NoticeOptions['categories'],id:string)=>options.find(option=>option.id===id)?.label||id
const filtered=computed(()=>notices.value.filter(n=>`${n.title} ${n.body} ${n.category}`.toLowerCase().includes(search.value.toLowerCase())))
onMounted(async()=>{await session.refresh();if(session.user.value){try{const response=await $fetch<{notices:Notice[];noticeOptions:NoticeOptions}>('/api/notices');notices.value=response.notices;noticeOptions.value=response.noticeOptions}catch(e){error.value=apiMessage(e)}}loading.value=false})
</script>
<template><div class="container page"><div class="page-heading"><div class="eyebrow">Comunicação interna</div><h1>Mural da Operação</h1><p>Avisos e orientações compartilhados pela liderança para manter a equipe alinhada.</p></div><div v-if="loading" class="empty">Carregando comunicados...</div><div v-else-if="!session.user.value" class="panel panel-pad"><h2>Conteúdo restrito à operação</h2><p class="muted">Faça login para acessar os comunicados internos.</p><NuxtLink to="/login" class="btn btn-primary">Entrar</NuxtLink></div><div v-else><div v-if="error" class="error">{{error}}</div><div class="search-row"><input v-model="search" class="search-input" placeholder="Pesquisar comunicados..." type="search"></div><div v-if="filtered.length" class="list-grid"><NuxtLink v-for="notice in filtered" :key="notice.id" :to="`/mural/${notice.id}`" class="list-card"><div class="v-space"><span v-if="notice.pinned" class="pill">📌 Fixado</span><span :class="['pill',notice.priority==='critical'?'red':'muted']">{{optionLabel(noticeOptions.categories,notice.category)}}</span><span v-if="notice.requires_ack&&!notice.acknowledged" class="pill amber">Leitura pendente</span></div><h3>{{notice.title}}</h3><p>{{notice.body.slice(0,180)}}{{notice.body.length>180?'…':''}}</p><div class="list-meta"><span>{{formatDate(notice.published_at)}}</span><span>{{notice.author_name}}</span></div></NuxtLink></div><div v-else class="empty">Nenhum comunicado encontrado.</div></div></div></template>
